/**
 * `Required_` names the columns an INSERT must supply. Everything else is
 * optional, because it is either nullable or filled in by a default or a
 * trigger — which is how the generated types model it too.
 */
type TableDef<Row, Required_ extends keyof Row> = {
  Row: Row;
  Insert: Pick<Row, Required_> & Partial<Omit<Row, Required_>>;
  Update: Partial<Row>;
  Relationships: [];
};

/**
 * The four browse lists — makes, body styles, categories and destination
 * countries — share one shape, so they share one row type.
 */
export type TaxonomyRow = {
  id: string;
  slug: string;
  name: string;
  image_url: string | null;
  sort_order: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
};

/** Makes carry a logo rather than a tile image; otherwise identical. */
export type MakeRow = Omit<TaxonomyRow, "image_url"> & { logo_url: string | null };

export const DRIVE_SIDES = ["right", "left", "both"] as const;
export type DriveSide = (typeof DRIVE_SIDES)[number];

export const DRIVE_SIDE_LABELS: Record<DriveSide, string> = {
  right: "Right-hand drive",
  left: "Left-hand drive",
  both: "Either",
};

/**
 * A destination market. `drive_side` is what makes "Search By Country" a real
 * filter: nothing links a vehicle to a destination, but a market takes the
 * steering side it drives on, and that is recorded on every vehicle.
 * `vehicle_count` is an optional manual override for the figure on the tile.
 */
export type CountryRow = TaxonomyRow & {
  vehicle_count: number | null;
  drive_side: DriveSide;
};

export const TAXONOMIES = ["makes", "body_styles", "categories", "countries"] as const;
export type TaxonomyName = (typeof TAXONOMIES)[number];

export const TAXONOMY_LABELS: Record<TaxonomyName, string> = {
  makes: "Makes",
  body_styles: "Body Styles",
  categories: "Categories",
  countries: "Countries",
};

type GeneratedPublic = Generated["public"];
type GeneratedVehicles = GeneratedPublic["Tables"]["vehicles"];

/** The generated vehicle row plus the columns the dashboard added. */
export type VehicleRow = GeneratedVehicles["Row"] & {
  locked_fields: string[];
  is_manual: boolean;
  is_featured: boolean;
};

type VehicleExtras = { locked_fields: string[]; is_manual: boolean; is_featured: boolean };

/** Brand and contact details shown in the header, footer and Contact page. */
export type ContactSettings = {
  name: string;
  tagline: string;
  phone: string;
  email: string;
  address: string;
  /** Empty means fall back to the lettermark built from the company name. */
  logo_url: string;
  /** The badge in the header, e.g. "JPY, ¥". */
  currency_label: string;
};

