/**
 * A repeatable item within a page: a buying step, an About statistic, or one of
 * the home page's promo panels. `variant` decides which slot in the home hero
 * grid a block fills; it is ignored on the other pages.
 */
export type PageBlockRow = {
  id: string;
  page_slug: string;
  title: string;
  body: string | null;
  image_url: string | null;
  cta_label: string | null;
  cta_href: string | null;
  variant: string;
  ends_at: string | null;
  sort_order: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
};

