/** Pages whose hero carries an image and a call-to-action button. */
export const PAGES_WITH_HERO_IMAGE: EditablePage[] = ["home"];

export type AdminTables = {
  user_roles: TableDef<UserRoleRow, "user_id" | "role">;
  site_settings: TableDef<SiteSettingRow, "key">;
  page_content: TableDef<PageContentRow, "slug" | "title" | "hero_title">;
  page_blocks: TableDef<PageBlockRow, "page_slug" | "title">;
  nav_items: TableDef<NavItemRow, "label" | "href">;
  saved_vehicles: TableDef<SavedVehicleRow, "customer_id" | "vehicle_id">;
  customers: TableDef<CustomerRow, "email">;
  // ref_no and customer_id are assigned by the inquiries_before_insert trigger.
  inquiries: TableDef<InquiryRow, "email">;
  inquiry_documents: TableDef<InquiryDocumentRow, "inquiry_id" | "title" | "storage_path">;
  inquiry_notes: TableDef<InquiryNoteRow, "inquiry_id" | "note">;
  inquiry_status_history: TableDef<InquiryStatusHistoryRow, "inquiry_id" | "to_status">;
  makes: TableDef<MakeRow, "slug" | "name">;
  body_styles: TableDef<TaxonomyRow, "slug" | "name">;
  categories: TableDef<TaxonomyRow, "slug" | "name">;
  countries: TableDef<CountryRow, "slug" | "name">;
  vehicles: {
    Row: VehicleRow;
    Insert: GeneratedVehicles["Insert"] & Partial<VehicleExtras>;
    Update: GeneratedVehicles["Update"] & Partial<VehicleExtras>;
    Relationships: GeneratedVehicles["Relationships"];
  };
};

/**
 * The generated Database plus the admin tables. `vehicles` is replaced rather
 * than intersected, so the added columns do not collide with the generated
 * definition of the same table.
 */
export type AppDatabase = Omit<Generated, "public"> & {
  public: Omit<GeneratedPublic, "Tables"> & {
    Tables: Omit<GeneratedPublic["Tables"], "vehicles"> & AdminTables;
  };
};

export const DOCUMENT_BUCKET = "inquiry-docs";
